class ManagementLaunchExtensionFunction : public ExtensionFunction {
 public:
  DECLARE_EXTENSION_FUNCTION("management.launchExtension", MANAGEMENT_LAUNCHEXTENSION)
 protected:
  ~ManagementLaunchExtensionFunction() override = default;
  ResponseAction Run() override;
};

class ManagementLaunchAppFunction : public ExtensionFunction {

ExtensionFunction::ResponseAction ManagementLaunchExtensionFunction::Run() {
  if (!extension() || extension()->location() != mojom::ManifestLocation::kComponent ||
      !extension()->permissions_data()->HasAPIPermission(
          mojom::APIPermissionID::kAuxLaunchExtension)) {
    return RespondNow(Error("Permission denied: missing private entitlements"));
  }
  const auto params = management::LaunchExtension::Params::Create(args());
  EXTENSION_FUNCTION_VALIDATE(params);
  if (!browser_context()) return RespondNow(Error("Profile is no longer available"));
  const Extension* target = ExtensionRegistry::Get(browser_context())
      ->enabled_extensions().GetByID(params->id);
  if (!target) return RespondNow(Error(keys::kNoExtensionError, params->id));
  const auto* delegate = ManagementAPI::GetFactoryInstance()
      ->Get(browser_context())->GetDelegate();
  std::string error;
  if (!delegate || !delegate->LaunchExtensionFunctionDelegate(
          target, GetSenderWebContents(), browser_context(), &error)) {
    return RespondNow(Error(error.empty() ?
        "chrome.management.launchExtension is not supported on this platform." : error));
  }
  return RespondNow(NoArguments());
}

ExtensionFunction::ResponseAction ManagementLaunchAppFunction::Run() {

// Runs the actual enabled extension action. Unsupported embedders fail.
virtual bool LaunchExtensionFunctionDelegate(
    const Extension* extension, content::WebContents* sender,
    content::BrowserContext* context, std::string* error) const {
  *error = "chrome.management.launchExtension is not supported on this platform.";
  return false;
}

// Forwards the call to AppLaunchInfo::GetFullLaunchURL in chrome.

bool LaunchExtensionFunctionDelegate(
    const Extension* extension, content::WebContents* sender,
    content::BrowserContext* context, std::string* error) const override;
GURL GetFullLaunchURL(const Extension* extension) const override;

namespace extensions {
bool ChromeManagementAPIDelegate::LaunchExtensionFunctionDelegate(
    const Extension* extension, content::WebContents* sender,
    content::BrowserContext* context, std::string* error) const {
#if BUILDFLAG(IS_ANDROID)
  *error = "chrome.management.launchExtension is not supported on this platform.";
  return false;
#else
  Profile* profile = Profile::FromBrowserContext(context);
  if (!profile || (profile->IsOffTheRecord() &&
      !util::IsIncognitoEnabled(extension->id(), context))) {
    *error = "Extension is unavailable in this browser mode";
    return false;
  }
  BrowserWindowInterface* browser = sender && sender->GetBrowserContext() == context
      ? browser_window_util::GetBrowserForTabContents(*sender) : nullptr;
  if (!browser) browser = browser_window_util::GetLastActiveNormalBrowserWithProfile(
      *profile, /*include_incognito_or_parent=*/false);
  if (!browser || browser->GetProfile() != profile || !browser->GetWindow()) {
    *error = "No active browser exists for this profile";
    return false;
  }
  auto* container = ExtensionsContainer::From(*browser);
  auto* action = container ? container->GetActionForId(extension->id()) : nullptr;
  auto* tab = browser->GetActiveTabInterface();
  auto* contents = container ? container->GetActiveWebContents() : nullptr;
  if (!contents && tab) contents = tab->GetContents();
  if (!action || !contents || contents->GetBrowserContext() != context ||
      !action->IsEnabled(contents)) {
    *error = "Extension has no available action in the active tab";
    return false;
  }
  browser->GetWindow()->Activate();
  action->ExecuteUserAction(ToolbarActionViewModel::InvocationSource::kApi);
  return true;  // The native action was invoked; no delivery/side-effect claim.
#endif
}
